class Solution:
    def maxSum(self, nums: list[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            # plain max subarray (Kadane)
            best = cur = nums[0]
            for x in nums[1:]:
                cur = x if x > cur + x else cur + x
                if cur > best:
                    best = cur
            return best
        gsorted = sorted(nums)
        bl = bisect_left
        br = bisect_right
        insort = insort_left
        ans = -10**30
        for l in range(n):
            xl = nums[l]
            Sin = [xl]
            Sout = sorted(nums[:l] + nums[l + 1:])
            Sout_len = n - 1
            kk = 1 if n >= 2 else 0
            A = xl if kk else 0
            B = Sout[-1] if kk else 0
            if n >= 2:
                v = gsorted[n - 2]
                if xl < v:
                    In_c = 1
                    In_s = xl
                else:
                    In_c = 0
                    In_s = 0
                q2 = br(Sout, v)
                Out_c = Sout_len - q2
                Out_s = sum(Sout[q2:])
            else:
                v = 0
                In_c = In_s = Out_c = Out_s = 0
            if kk == 0:
                gain = 0
            elif Sout[Sout_len - kk] >= Sin[kk - 1]:
                gain = B - A
            else:
                gain = v * In_c - In_s + Out_s - v * Out_c
            base = xl
            cand = base + gain
            if cand > ans:
                ans = cand
            nm = n - 1
            m = 1
            Sout_pop = Sout.pop
            for r in range(l + 1, n):
                x = nums[r]
                m += 1
                nm -= 1
                # v* update: v* = gsorted[n - m - 1] = gsorted[nm - 1]
                if nm >= 1:
                    v_new = gsorted[nm - 1]
                    if v_new != v:
                        q1 = bl(Sin, v_new)
                        q2 = bl(Sin, v)
                        if q2 > q1:
                            In_c -= q2 - q1
                            In_s -= sum(Sin[q1:q2])
                        q1 = br(Sout, v_new)
                        q2 = br(Sout, v)
                        if q2 > q1:
                            Out_c += q2 - q1
                            Out_s += sum(Sout[q1:q2])
                        v = v_new
                kk_new = k if k < m else m
                if nm < kk_new:
                    kk_new = nm
                # insert x into inside (old kk), fused bisect+insert
                insort(Sin, x)
                if kk:
                    if x <= Sin[kk - 1]:
                        A += x - Sin[kk]
                if x < v:
                    In_c += 1
                    In_s += x
                if kk_new > kk:
                    A += Sin[kk_new - 1]
                elif kk_new < kk:
                    A -= Sin[kk_new]
                # remove x from outside
                p = bl(Sout, x)
                if kk_new < kk:
                    B -= Sout[Sout_len - kk]
                    if p >= Sout_len - kk_new:
                        B -= x
                        B += Sout[Sout_len - kk_new - 1]
                    Sout_pop(p)
                else:
                    if p >= Sout_len - kk:
                        B -= x
                        if Sout_len - kk - 1 >= 0:
                            B += Sout[Sout_len - kk - 1]
                    Sout_pop(p)
                    if kk_new > kk:
                        B += Sout[Sout_len - 1 - kk_new]
                Sout_len -= 1
                if x > v:
                    Out_c -= 1
                    Out_s -= x
                kk = kk_new
                # evaluate window [l, r]
                base += x
                if kk == 0:
                    gain = 0
                else:
                    a0 = Sin[kk - 1]
                    b0 = Sout[Sout_len - kk]
                    if b0 >= a0:
                        gain = B - A
                    else:
                        gain = v * In_c - In_s + Out_s - v * Out_c
                cand = base + gain
                if cand > ans:
                    ans = cand
        return ans

from collections import deque

class Solution:
    def maximumSum(self, nums: list[int], m: int, l: int, r: int) -> int:
        n = len(nums)
        pref = [0] * (n + 1)
        for i, x in enumerate(nums, 1):
            pref[i] = pref[i - 1] + x

        # More than floor(n / l) subarrays can never fit.
        max_k = min(m, n // l)
        NEG = -10**30

        # dp_prev[j] = best sum using exactly (k-1) subarrays inside prefix nums[:j]
        dp_prev = [0] * (n + 1)  # k = 0: choose nothing anywhere
        ans = NEG

        for _ in range(1, max_k + 1):
            dp_cur = [NEG] * (n + 1)
            dq = deque()  # indices j, with dp_prev[j] - pref[j] decreasing

            for i in range(1, n + 1):
                # A subarray ending at i may start at j in [i-r, i-l].
                add = i - l
                if add >= 0 and dp_prev[add] != NEG:
                    v = dp_prev[add] - pref[add]
                    while dq and dp_prev[dq[-1]] - pref[dq[-1]] <= v:
                        dq.pop()
                    dq.append(add)

                left = i - r
                while dq and dq[0] < left:
                    dq.popleft()

                if dq:
                    j = dq[0]
                    cand = pref[i] + dp_prev[j] - pref[j]
                    if cand > dp_cur[i - 1]:
                        dp_cur[i] = cand
                    else:
                        dp_cur[i] = dp_cur[i - 1]
                else:
                    dp_cur[i] = dp_cur[i - 1]

            if dp_cur[n] > ans:
                ans = dp_cur[n]
            dp_prev = dp_cur

        return ans

