            divs = []
            x = 1
            while x * x <= start_val:
                if start_val % x == 0:
                    divs.append(x)
                    if x * x != start_val:
                        divs.append(start_val // x)
                x += 1
            divs.sort()
            cand = [c for c in cand if c in set(divs)] if len(cand) > 20 else list(cand)
            # simpler: candidates that divide start_val
            cand = [c for c in {start_val} | {gcd(start_val, S[k]) for k in range(a + 1, b + 1)} if start_val % c == 0]

            for g in cand:
                lo, hi = None, None
                for k in range(a, b + 1):
                    gk = gcd(gL, S[k])
                    if gk == g:
                        if lo is None:
                            lo = k
                        hi = k
                    elif gk % g == 0:
                        if lo is None:
                            lo = k
                        hi = k
                if lo is None:
                    continue
                cnt = split_count(g)
                if lo > 1:
                    cnt -= max(0, min(hi, n - 1) - lo + 1)
                events.setdefault((lo, hi), 0)
                events[(lo, hi)] = max(events[(lo, hi)], cnt)

            # interval stabbing
            pts = sorted(events.keys())
            for (lo, hi), c in events.items():
                for k in range(lo, min(hi, n - 1) + 1):
                    pass  # placeholder (shouldn't iterate for large)
            # brute force over k in block since block total size is O(n log Amax) overall? Not guaranteed.
            # Instead evaluate max over k via events: for each k, sum c of events covering k
            # Collect boundaries
            ks = sorted(set([a] + [lo for (lo, hi) in events] + [hi + 1 for (lo, hi) in events] + [b + 1]))
            for idx in range(len(ks) - 1):
                k = ks[idx]
                if k > b:
                    break
                s = 0
                for (lo, hi), c in events.items():
                    if lo <= k <= hi:
                        s = max(s, c)
                ans = max(ans, s)
            a = b + 1

        return ans

