            return cntBit.kth(c)

        def succ_peak(i):
            # smallest peak index > i, or -1
            c = cntBit.sum(i)
            if cntBit.sum(n - 1) == c:
                return -1
            return cntBit.kth(c + 1)

        def add_peak(i):
            p = pred_peak(i)
            s = succ_peak(i)
            cntBit.add(i, 1)
            wBit.add(i, 0 if p == -1 else C2(i - p))
            if s != -1:
                old = C2(s - p) if p != -1 else 0
                wBit.add(s, C2(s - i) - old)

        def remove_peak(i):
            p = pred_peak(i)
            s = succ_peak(i)
            cntBit.add(i, -1)
            wBit.add(i, -(0 if p == -1 else C2(i - p)))
            if s != -1:
                old = C2(s - i)
                new = C2(s - p) if p != -1 else 0
                wBit.add(s, new - old)

        ans = []
        for q in queries:
            if q[0] == 2:
                idx, val = q[1], q[2]
                if nums[idx] == val:
                    continue
                nums[idx] = val
                for j in (idx - 1, idx, idx + 1):
                    if 1 <= j <= n - 2:
                        now = nums[j] > nums[j - 1] and nums[j] > nums[j + 1]
                        if now and not is_peak[j]:
                            is_peak[j] = True
                            add_peak(j)
                        elif not now and is_peak[j]:
                            is_peak[j] = False
                            remove_peak(j)
            else:
                l, r = q[1], q[2]
                total = C2(r - l)  # subarrays of length >= 3 in [l, r]
                c_l = cntBit.sum(l)
                c_r = cntBit.sum(r - 1)
                cnt = c_r - c_l  # peaks strictly inside (l, r)
                if cnt == 0:
                    ans.append(0)
                    continue
                f = cntBit.kth(c_l + 1)   # first peak in (l, r)
                last = cntBit.kth(c_r)    # last peak in (l, r)
                sumW = wBit.sum(r - 1) - wBit.sum(l)
                p = pred_peak(f)
                wf = 0 if p == -1 else C2(f - p)
                internal = sumW - wf      # sum of C2(gap) between consecutive peaks inside
                nopeak = C2(f - l) + internal + C2(r - last)
                ans.append(total - nopeak)
        return ans

class Solution:
    def maxPrimeSubset(self, n: int, s: int) -> list[int]:
        # Sieve of Eratosthenes to find all primes <= n
        if n < 2:
            return []
        is_prime = [True] * (n + 1)
        is_prime[0] = is_prime[1] = False
        for i in range(2, int(n ** 0.5) + 1):
            if is_prime[i]:
                for j in range(i * i, n + 1, i):
                    is_prime[j] = False
        primes = [i for i in range(2, n + 1) if is_prime[i]]

        # dp[j] = best subset achieving exact sum j, stored as (count, tuple_of_primes)
        # "best" = fewest primes, then lexicographically smallest tuple.
        # Primes are processed in increasing order, so appending p to a tuple of
        # smaller primes keeps it sorted, and (count, tuple) comparison in Python
        # matches the required ordering (count first, then lexicographic).
        dp = [None] * (s + 1)
        dp[0] = (0, ())
        for p in primes:
            if p > s:
                break
            for j in range(s, p - 1, -1):
                prev = dp[j - p]
                if prev is not None:
                    cand = (prev[0] + 1, prev[1] + (p,))
                    if dp[j] is None or cand < dp[j]:
                        dp[j] = cand

        # Find the largest achievable sum j <= s
        best = -1
        for j in range(s, 0, -1):
            if dp[j] is not None:
                best = j
                break

        if best <= 0:
            return []
        return list(dp[best][1])

