        MOD = 10**9 + 7

        def fib(k: int):
            """Return (F_k, F_{k+1}) for standard Fibonacci with F_0=0, F_1=1."""
            if k == 0:
                return (0, 1)
            a, b = fib(k >> 1)
            c = (a * (2 * b - a)) % MOD
            d = (a * a + b * b) % MOD
            if k & 1:
                return (d, (c + d) % MOD)
            else:
                return (c, d)

        f_n, _ = fib(n)
        return (2 * f_n) % MOD

