    def longestSubarray(self, nums: list[int], k: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        max_len = 0

        # Check all subarrays in O(n^2)
        for i in range(n):
            sum_val = 0
            seen_mods = set()  # stores 2*nums[p] % k for p in [i..j]
            for j in range(i, n):
                sum_val += nums[j]
                cur_mod = sum_val % k

                # Check if current sum is divisible by k (case 1)
                if cur_mod == 0:
                    max_len = max(max_len, j - i + 1)

                # Add 2*nums[j] % k to seen_mods (for possible negation of nums[j] or earlier elements)
                two_mod = (2 * nums[j]) % k
                seen_mods.add(two_mod)

                # Check if cur_mod is in seen_mods (i.e., if any 2*nums[p] % k == cur_mod for p in [i..j], meaning negating nums[p] makes sum divisible by k; case 2)
                if cur_mod in seen_mods:
                    max_len = max(max_len, j - i + 1)

