                for y in range(1, MAX_VAL + 1):
                    if freq[y] == 0:
                        continue
                    if x + y <= MAX_VAL and freq[x + y] > 0:
                        invalid = True
                        break

                if not invalid:
                    # Check if some y+z equals x from the window
                    for y in range(1, MAX_VAL + 1):
                        if freq[y] == 0:
                            continue
                        z = x - y
                        if z < 1 or z > MAX_VAL:
                            continue
                        if freq[z] > 0:
                            # If y == z we need at least two copies of y in the window
                            if y == z and freq[y] < 2:
                                continue
                            else:
                                invalid = True
                                break

                if invalid:
                    break

                # Include nums[r] in the window
                freq[x] += 1
                cur_len = r - l + 1
                if cur_len > best:
                    best = cur_len

        return best

