class Solution:
    def maximumSaleItems(self, items: List[List[int]], budget: int) -> int:
        n = len(items)
        factors = [items[i][0] for i in range(n)]
        prices = [items[i][1] for i in range(n)]

        # Compute free_count[i]: number of j != i such that factor_i divides factor_j
        free_count = [0] * n
        for i in range(n):
            f_i = factors[i]
            for j in range(n):
                if i == j:
                    continue
                f_j = factors[j]
                if f_j % f_i == 0:
                    free_count[i] += 1

        best = 0
        # Enumerate all subsets S of item types to buy at least one copy
        # mask bit i = 1 means item i is in S (bought at least once)
        for mask in range(1 << n):
            cost_S = 0
            for i in range(n):
                if mask & (1 << i):
                    cost_S += prices[i]
            if cost_S > budget:
                continue
            size_S = bin(mask).count("1")
            free_S = 0
            for i in range(n):
                if mask & (1 << i):
                    free_S += free_count[i]

            # If S is empty, just buy cheapest items
            if size_S == 0:
                min_price = min(prices)
                extra = budget // min_price
                total = extra
                if total > best:
                    best = total
                continue

            min_price_in_S = min(prices[i] for i in range(n) if mask & (1 << i))
            extra = (budget - cost_S) // min_price_in_S
            total = size_S + free_S + extra
            if total > best:
                best = total

        return best

class Solution:
    def maximumSaleItems(self, items: list[list[int]], budget: int) -> int:
        n = len(items)
        if n == 0:
            return 0

        factors = [item[0] for item in items]
        prices = [item[1] for item in items]

        max_f = max(factors)
        freq = [0] * (max_f + 1)
        for f in factors:
            freq[f] += 1

        total_div = [0] * (max_f + 1)
        for f in range(1, max_f + 1):
            for m in range(f, max_f + 1, f):
                total_div[f] += freq[m]

        d_list = [total_div[f] - 1 for f in factors]

        # Pair (price, d) and sort by price
        items_with_d = [(prices[i], d_list[i]) for i in range(n)]
        items_with_d.sort(key=lambda x: x[0])

        rem = budget
        total_copies = 0

        # Phase 1: high-value copies (each gives 2 copies: purchased + free)
        for p, d in items_with_d:
            if d == 0:
                continue
            if rem < p:
                continue
            max_high = d
            buy_high = min(max_high, rem // p)
            if buy_high > 0:
                total_copies += 2 * buy_high
                rem -= buy_high * p

        # Phase 2: low-value copies (each gives 1 copy: purchased only)
        for p, d in items_with_d:
            if rem < p:
                continue
            buy_low = rem // p
            if buy_low > 0:
                total_copies += buy_low
                rem -= buy_low * p

        return total_copies

class Solution:
    def maxScore(self, grid: list[list[int]]) -> int:
        m = len(grid)
        n = len(grid[0])

        # DFS for player1 paths (right/down)
        def dfs1(i, j, path):
            if i == m-1 and j == n-1:
                return [path]
            res = []
            if j+1 < n:
                ns = set(path)
                ns.add((i, j+1))
                res.extend(dfs1(i, j+1, ns))
            if i+1 < m:
                ns = set(path)
                ns.add((i+1, j))
                res.extend(dfs1(i+1, j, ns))
            return res

        # DFS for player2 paths (right/up)
        def dfs2(i, j, path):
            if i == 0 and j == n-1:
                return [path]
            res = []
            if j+1 < n:
                ns = set(path)
                ns.add((i, j+1))
                res.extend(dfs2(i, j+1, ns))
            if i-1 >= 0:
                ns = set(path)
                ns.add((i-1, j))
                res.extend(dfs2(i-1, j, ns))
            return res

        start1 = {(0,0)}
        all1 = dfs1(0, 0, start1)
        start2 = {(m-1, 0)}
        all2 = dfs2(m-1, 0, start2)

        best = -10**9
        for p1 in all1:
            for p2 in all2:
                inter = p1 & p2
                s = sum(grid[i][j] for (i, j) in inter)
                if s > best:
                    best = s
        return best

