class Solution:
    def maxScore(self, nums: List[int], maxVal: int) -> int:
        n = len(nums)
        if n == 0:
            return 0

        max_num = max(nums)
        M = max(maxVal, max_num)

        # Precompute smallest prime factor (spf) up to M
        spf = list(range(M + 1))
        for i in range(2, int(M ** 0.5) + 1):
            if spf[i] == i:
                for j in range(i * i, M + 1, i):
                    if spf[j] == j:
                        spf[j] = i

        # freq[x] = count of x in nums
        freq = [0] * (M + 1)
        for x in nums:
            if x <= M:
                freq[x] += 1

        # cnt[d] = number of nums divisible by d
        cnt = [0] * (M + 1)
        for d in range(1, M + 1):
            total = 0
            for k in range(d, M + 1, d):
                total += freq[k]
            cnt[d] = total

        # totalNonCoPrime[v] = number of nums[j] with gcd(v, nums[j]) != 1
        # using inclusion-exclusion over prime factors of v
        totalNonCoPrime = [0] * (M + 1)
        for v in range(1, M + 1):
            x = v
            factors = []
            while x > 1:
                p = spf[x]
                factors.append(p)
                while x % p == 0:
                    x //= p
            factors = sorted(set(factors))
            k = len(factors)
            total = 0
            # iterate over non-empty subsets
            for mask in range(1, 1 << k):
                prod = 1
                bits = 0
                for i in range(k):
                    if mask >> i & 1:
                        prod *= factors[i]
                        bits += 1
                if prod > M:
                    continue
                term = cnt[prod]
                if bits % 2 == 1:
                    total += term
                else:
                    total -= term
            totalNonCoPrime[v] = total

        # base[v] = v - totalNonCoPrime[v]
        # only needed for v <= maxVal for change option
        base = [0] * (M + 1)
        for v in range(1, M + 1):
            base[v] = v - totalNonCoPrime[v]

        # Sort v=1..maxVal by base[v] descending
        bases_list = [(base[v], v) for v in range(1, maxVal + 1)]
        bases_list.sort(key=lambda x: x[0], reverse=True)

        # Helper gcd
        def gcd(a, b):
            if b == 0:
                return a
            return gcd(b, a % b)

        best_score = -10**9

        for i in range(n):
            num = nums[i]
            # Keep option
            # totalNonCoPrime[num] includes j=i
            # costOther_keep = number of j != i with gcd(num, nums[j]) != 1
            # = totalNonCoPrime[num] - (1 if num != 1 else 0) since gcd(num, num) != 1 iff num != 1
            keep_costOther = totalNonCoPrime[num] - (1 if num != 1 else 0)
            keep_score = num - keep_costOther  # cost_i = 0
            best_score = max(best_score, keep_score)

            # Change option: v != num, v <= maxVal
            # Score(i, v) = base[v] - 1 + [gcd(v, num) != 1]
            #   = { base[v] - 1 if gcd(v, num) = 1; base[v] if gcd(v, num) != 1 }

            if num == 1:
                # gcd(1, v) = 1 for all v, so Score = base[v] - 1 for all v
                if bases_list:
                    # max (base[v] - 1)
                    maxBase1Score = bases_list[0][0] - 1
                else:
                    maxBase1Score = -10**9
                changeScore = maxBase1Score  # no v with gcd≠1
                best_score = max(best_score, changeScore)
                continue

            # Scan bases_list to find max_base_co_prime and max_base_not_co_prime
            max_base_co_prime = -10**9  # max base[v] for gcd(v, num)=1
            max_base_not_co_prime = -10**9  # max base[v] for gcd(v, num)!=1
            for base_val, v in bases_list:
                if v == num:
                    # v = num is the keep option, skip for change
                    continue
                if gcd(v, num) == 1:
                    if base_val > max_base_co_prime:
                        max_base_co_prime = base_val
                else:
                    if base_val > max_base_not_co_prime:
                        max_base_not_co_prime = base_val

            # For change, Score = base[v] - 1 if gcd=1, base[v] if gcd!=1
            maxBase1Score = max_base_co_prime - 1 if max_base_co_prime != -10**9 else -10**9
            maxBase2Score = max_base_not_co_prime if max_base_not_co_prime != -10**9 else -10**9
            changeScore = max(maxBase1Score, maxBase2Score)

            # Also consider changing to v=num? No, change option requires v != num
            # But keep option already covers v=num
            best_score = max(best_score, changeScore)

        return best_score

class Solution:
    def maxSum(self, nums: list[int], k: int) -> int:
        n = len(nums)
        if k == 0:
            # Kadane
            best = nums[0]
            cur = nums[0]
            for i in range(1, n):
                cur = max(nums[i], cur + nums[i])
                best = max(best, cur)
            return best

        best = max(nums)  # at least max element

        def dfs(arr, depth_left):
            nonlocal best
            # compute current max subarray sum
            cur_best = arr[0]
            cur = arr[0]
            for val in arr[1:]:
                cur = max(val, cur + val)
                cur_best = max(cur_best, cur)
            best = max(best, cur_best)

            if depth_left == 0:
                return
            for i in range(n):
                for j in range(i+1, n):
                    arr[i], arr[j] = arr[j], arr[i]
                    dfs(arr, depth_left-1)
                    arr[i], arr[j] = arr[j], arr[i]

        dfs(nums[:], k)
        return best

class Solution:
    def maxSum(self, nums: list[int], k: int, mul: int) -> int:
        # Select the k largest elements
        nums.sort(reverse=True)
        selected = nums[:k]

        # Process in descending order (largest first) to use highest multipliers on largest numbers
        total = 0
        for i in range(k):
            current_multiplier = mul - i
            if current_multiplier > 0:
                # Multiply gives at least as much as addition (since num >= 1 and multiplier >= 1)
                total += selected[i] * current_multiplier
            else:
                # Addition is better when multiplier <= 0
                total += selected[i]

        return total

import heapq

class Solution:
    def maxTotalValue(self, value: list[int], decay: list[int], m: int) -> int:
        MOD = 10**9 + 7

        # Max-heap: store (-value[i] - decay[i]*t, i, t) where t is selections made so far
        # The value represented is value[i] - decay[i] * t (next selection value)
        heap = []

        for i in range(len(value)):
            if value[i] > 0:
                # First selection: t=0 selections made so far, value = value[i] - decay[i]*0 = value[i]
                heapq.heappush(heap, (-value[i], i, 0))

        total = 0

        for _ in range(m):
            if not heap:
                break

            neg_val, i, t = heapq.heappop(heap)
            cur_val = -neg_val  # = value[i] - decay[i] * t

            if cur_val <= 0:
                heapq.heappush(heap, (neg_val, i, t))
                break

            total += cur_val

            # Next selection value: value[i] - decay[i] * (t + 1)
            next_val = value[i] - decay[i] * (t + 1)
            if next_val > 0:
                heapq.heappush(heap, (-next_val, i, t + 1))

        return total % MOD

class Solution:
    def maxTotal(self, nums: list[int], s: str) -> int:
        n = len(nums)
        i = 0
        total = 0
        while i < n:
            if s[i] == '1':
                l = i
                while i < n and s[i] == '1':
                    i += 1
                r = i - 1
                k = r - l + 1
                vals = []
                if l > 0:
                    vals.append(nums[l-1])
                for j in range(l, r+1):
                    vals.append(nums[j])
                vals.sort(reverse=True)
                total += sum(vals[:k])
            else:
                i += 1
        return total

