            # If no r < period_minus_X, all cars can use any light
            if max_r_lt < 0:  # no car needs special light
                return True
            # Find smallest light > max_r_lt
            # lights is sorted
            left, right = 0, len(lights)
            while left < right:
                mid = (left + right) // 2
                if lights[mid] <= max_r_lt:
                    left = mid + 1
                else:
                    right = mid
            # left is first index with lights[left] > max_r_lt, or len(lights) if not found
            return left < len(lights)

        # Binary search for smallest X with feasible(X) = True
        lo, hi = 0, period - 1
        # Binary search in [0, period-1]
        while lo < hi:
            mid = (lo + hi) // 2
            if feasible(mid):
                hi = mid
            else:
                lo = mid + 1
        return lo

