                b = ss[j + k]
                if a == b:
                    k += 1
                    continue
                if a > b:
                    i = i + k + 1
                    if i <= j:
                        i = j + 1
                    k = 0
                else:  # a < b
                    j = j + k + 1
                    if j <= i:
                        j = i + 1
                    k = 0
            start = min(i, j)
            return ss[start:start + n]

        from collections import defaultdict
        groups = defaultdict(int)
        for word in words:
