class Solution:
    def minOperations(self, nums: List[int]) -> int:
        n = len(nums)
        # case1: rotation only (nums rotated left by idx0 equals sorted)
        idx0 = nums.index(0)
        ok1 = True
        for i in range(n):
            j = (i + idx0) % n
            if nums[j] != i:
                ok1 = False
                break
        ans = float('inf')
        if ok1:
            ans = idx0

        # case3: rotation then reverse (nums rotated left by idx_n1 equals reverse sorted)
        idx_n1 = nums.index(n - 1)
        ok3 = True
        for i in range(n):
            j = (i + idx_n1) % n
            if nums[j] != (n - 1 - i):
                ok3 = False
                break
        if ok3:
            # need to rotate idx_n1 times then reverse -> ops = idx_n1 + 1
            ans = min(ans, idx_n1 + 1)

        # case2: reverse then rotation (reverse(nums) rotated left by idx0_rev equals sorted)
        rev_nums = nums[::-1]
        idx0_rev = rev_nums.index(0)
        ok2 = True
        for i in range(n):
            j = (i + idx0_rev) % n
            if rev_nums[j] != i:
                ok2 = False
                break
        if ok2:
            # reverse then rotate idx0_rev times -> ops = 1 + idx0_rev
            ans = min(ans, 1 + idx0_rev)

        if ans == float('inf'):
            return -1
        else:
            return ans

class Solution:
    def minOperations(self, s1: str, s2: str) -> int:
        # BFS for small strings (n <= 20) else attempt simple greedy? 
        # But examples are small, so BFS works.
        n = len(s1)
        if n != len(s2):
            return -1
        if s1 == s2:
            return 0
        from collections import deque
        start = s1
        target = s2
        visited = set([start])
        q = deque([(start, 0)])
        while q:
            cur, dist = q.popleft()
            if cur == target:
                return dist
            # operation 1: flip '0' -> '1'
            for i in range(n):
                if cur[i] == '0':
                    nxt = cur[:i] + '1' + cur[i+1:]
                    if nxt not in visited:
                        visited.add(nxt)
                        q.append((nxt, dist+1))
            # operation 2: flip two adjacent '1' -> '0'
            for i in range(n-1):
                if cur[i] == '1' and cur[i+1] == '1':
                    nxt = cur[:i] + '00' + cur[i+2:]
                    if nxt not in visited:
                        visited.add(nxt)
                        q.append((nxt, dist+1))
        return -1

class Solution:
    def minMaxWaitingTime(self, demand: list[int], fuel: list[int]) -> int:
        n = len(demand)

        from functools import lru_cache

        @lru_cache(maxsize=None)
        def dfs(idx, d0_rem, d1_rem, time0_free, time1_free, last_start_time):
            # idx: next car to serve
            # d0_rem, d1_rem: remaining fuel in dispensers at current time (when car idx becomes allowed)
            # time0_free, time1_free: when each dispenser becomes free (absolute time)
            # last_start_time: time when car idx-1 started (integer)

            if idx == n:
                return (0, 0)  # (max_wait for suffix, count for suffix)

            best_max_wait = float('inf')
            best_count = 0

            # Try dispenser 0 if enough fuel
            if d0_rem >= demand[idx]:
                start_time = max(last_start_time, time0_free)
                wait_time = start_time - last_start_time

                new_d0_rem = d0_rem - demand[idx]
                new_time0_free = start_time + demand[idx]

                max_wait_suffix, count_suffix = dfs(idx + 1, new_d0_rem, d1_rem, new_time0_free, time1_free, start_time)

                # If suffix can serve cars, total_max_wait = max(wait_time, max_wait_suffix)
                # If suffix cannot serve any cars, total_max_wait = wait_time
                if count_suffix > 0:
                    total_max_wait = max(wait_time, max_wait_suffix)
                else:
                    total_max_wait = wait_time

                total_count = 1 + count_suffix

                if total_count > best_count or (total_count == best_count and total_max_wait < best_max_wait):
                    best_count = total_count
                    best_max_wait = total_max_wait

            # Try dispenser 1 if enough fuel
            if d1_rem >= demand[idx]:
                start_time = max(last_start_time, time1_free)
                wait_time = start_time - last_start_time

                new_d1_rem = d1_rem - demand[idx]
                new_time1_free = start_time + demand[idx]

                max_wait_suffix, count_suffix = dfs(idx + 1, d0_rem, new_d1_rem, time0_free, new_time1_free, start_time)

                if count_suffix > 0:
                    total_max_wait = max(wait_time, max_wait_suffix)
                else:
                    total_max_wait = wait_time

                total_count = 1 + count_suffix

                if total_count > best_count or (total_count == best_count and total_max_wait < best_max_wait):
                    best_count = total_count
                    best_max_wait = total_max_wait

            # If no dispenser can serve car idx, return (0, 0) meaning serve 0 cars from here
            if best_count == 0:
                return (0, 0)

            return (best_max_wait, best_count)

        # Initial call: car 0 becomes allowed at time 0
        # Both dispensers are free at time 0
        max_wait_suffix, count = dfs(0, fuel[0], fuel[1], 0, 0, 0)

        if count == 0:
            return -1

        return int(max_wait_suffix)

class Solution:
    def getSum(self, nums: list[int]) -> int:
        n = len(nums)
        max_sum = max(nums)  # single element

        # odd centers
        for i in range(n):
            left = i
            right = i
            cur_sum = nums[i]
            # expand outward
            while left - 1 >= 0 and right + 1 < n and nums[left - 1] == nums[right + 1]:
                left -= 1
                right += 1
                cur_sum += nums[left] + nums[right]
                if cur_sum > max_sum:
                    max_sum = cur_sum

        # even centers
        for i in range(n - 1):
            if nums[i] == nums[i + 1]:
                left = i
                right = i + 1
                cur_sum = nums[i] + nums[i + 1]
                if cur_sum > max_sum:
                    max_sum = cur_sum
                while left - 1 >= 0 and right + 1 < n and nums[left - 1] == nums[right + 1]:
                    left -= 1
                    right += 1
                    cur_sum += nums[left] + nums[right]
                    if cur_sum > max_sum:
                        max_sum = cur_sum

        return max_sum

