from collections import Counter

class Solution:
    def validSubarrays(self, nums: list[int], k: int, queries: list[list[int]]) -> list[bool]:
        def is_valid(l, r):
            # Length must be even since all frequencies are even
            if (r - l + 1) % 2 != 0:
                return False

            sub = nums[l:r+1]

            # Count frequencies
            freq = Counter(sub)

            # Check exactly k distinct
            if len(freq) != k:
                return False

            # Check all frequencies are even
            for count in freq.values():
                if count % 2 != 0:
                    return False

            return True

        ans = []
        for l, r in queries:
            # Early filter: length must be even
            if (r - l + 1) % 2 == 0:
                ans.append(is_valid(l, r))
            else:
                ans.append(False)
        return ans

class Solution:
    def countValidSubarrays(self, nums: list[int], x: int) -> int:
        n = len(nums)
        count = 0

        for l in range(n):
            total = 0
            for r in range(l, n):
                total += nums[r]
                # Last digit is total % 10
                if total % 10 != x:
                    continue
                # First digit is the leftmost digit in decimal representation
                # nums[i] >= 1 so total >= 1, no leading zeros
                if int(str(total)[0]) == x:
                    count += 1

        return count
